    r"|^scripts/(build_browser_ext|fetch_vendor_assets|stage_extension_panel"
    r"|ext_package_guard|prune_flutter_assets)\."
    r"|^scripts/size_budget/fa-extension\.tsv$"
    r"|^\.github/workflows/(ci|build-macos|pages)\.yml$)'";

